package com.example

import com.example.ExamQuestionHelper.QSpec

internal object EnglishLiveExamAgreeModalsBank2 {
  private const val T = "Modals & Question Tags"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("You ___ read the exam instructions carefully before writing answers.", "should", "might", "would", "could have", "'Should' expresses strong, practical advice."),
    q("All candidates ___ bring their National Identity Card to the exam.", "must", "might", "could", "would", "'Must' indicates a strict obligation or rule."),
    q("Students ___ talk inside the silent reading section of the library.", "mustn't", "needn't", "don't have to", "mightn't", "'Mustn't' expresses strict prohibition."),
    q("You ___ worry about bringing extra paper; sheets are provided.", "needn't", "mustn't", "can't", "couldn't", "'Needn't' (or 'don't have to') means there is no necessity."),
    q("___ I borrow your English dictionary for a few minutes, please?", "May", "Must", "Should", "Will not", "'May I...' is the standard polite modal for asking permission."),
    q("When my grandfather was twenty, he ___ swim across the wide river.", "could", "can", "may", "must", "General ability in the past is expressed with 'could'."),
    q("Although the slope was steep, the hikers ___ reach the summit safely.", "were able to", "could be", "can", "may", "Specific single past achievement uses 'were able to' rather than 'could'."),
    q("Take an umbrella with you; it ___ rain later this evening.", "might", "mustn't", "ought", "had better to", "'Might' indicates a reasonable future possibility."),
    q("The lights are off and the gate is locked; they ___ have gone out.", "must", "can't", "shouldn't", "needn't", "Strong logical certainty about the present/past uses 'must have'."),
    q("That tall man ___ be Ruwan; Ruwan is currently away in Jaffna.", "can't", "must", "may", "ought to", "Logical impossibility uses 'can't be'."),
    q("Citizens ___ respect traffic signals to keep pedestrians safe.", "ought to", "might", "could", "would rather", "'Ought to' expresses moral and civic duty."),
    q("You ___ hurry if you want to catch the 6:30 express train.", "had better", "would rather", "ought", "used to", "'Had better + base verb' gives urgent advice with a warning."),
    q("I ___ stay at home and read than go out in this heavy storm.", "would rather", "had better", "ought to", "must", "'Would rather + V1 ... than ...' expresses personal preference."),
    q("___ you mind passing the salt container across the table?", "Would", "Should", "Must", "Might", "'Would you mind + V-ing' is a polite request form."),
    q("We ___ obey the referee's whistle on the football field.", "have to", "may", "might", "used to", "'Have to' indicates external rules or obligations."),
    q("Yesterday, I ___ wake up at five to catch the early school bus.", "had to", "must", "have to", "should to", "Past obligation always uses 'had to' (never 'musted')."),
    q("By next year, my sister ___ speak Japanese quite fluently.", "will be able to", "will can", "can be", "could", "Future ability uses 'will be able to' (never 'will can')."),
    q("You ___ have left your umbrella on the bus; look under the seat.", "might", "can't", "mustn't", "needn't to", "Possibility about a past event uses 'might have + V3'."),
    q("You ___ have shouted at the younger child; that was unkind.", "shouldn't", "mustn't", "needn't", "wouldn't", "'Shouldn't have + V3' expresses criticism or regret about the past."),
    q("We ___ have brought raincoats because the weather stayed sunny.", "needn't", "mustn't", "can't", "wouldn't", "'Needn't have + V3' means an action done was unnecessary."),
    q("___ we organize an English Day debate next term?", "Shall", "Will not", "Ought", "Need", "'Shall we...' makes a polite group suggestion."),
    q("___ I carry those heavy reference books to the staffroom for you?", "Shall", "Must", "Needn't", "Used", "'Shall I...' is used to offer help politely."),
    q("A good leader ___ always listen patiently to team members.", "should", "might", "needn't", "dare not", "'Should' expresses expected good conduct."),
    q("No one ___ enter the chemistry storeroom without teacher supervision.", "may", "need", "used to", "would", "'No one may...' states formal denial of permission."),
    q("He ___ play chess very well even before joining Grade 6.", "could", "can", "may", "will", "Past ability before a past age uses 'could'."),
    q("She ___ be at the library now; I saw her heading there.", "must", "can't", "wouldn't", "needn't", "Strong deduction based on evidence takes 'must be'."),
    q("You ___ wear a tie with the sports kit; it is optional.", "don't have to", "mustn't", "can't", "shouldn't", "'Don't have to' means it is optional, not prohibited."),
    q("Passengers ___ fasten their seatbelts during take-off and landing.", "must", "might", "could", "would rather", "Mandatory safety regulations take 'must'."),
    q("If you feel dizzy in the sun, you ___ drink plenty of water.", "should", "mustn't", "can't", "needn't", "Sensible health advice takes 'should'."),
    q("Could you ___ me where the nearest post office is?", "tell", "told", "telling", "to tell", "Modal verbs like 'Could' are always followed by the bare infinitive 'tell'."),
    q("She plays the sitar beautifully, ___?", "doesn't she", "does she", "isn't she", "didn't she", "Positive Simple Present verb 'plays' takes negative tag 'doesn't she?'."),
    q("They visited Sigiriya during the April holidays, ___?", "didn't they", "did they", "don't they", "weren't they", "Positive Simple Past 'visited' requires 'didn't they?'."),
    q("We haven't received the exam timetable yet, ___?", "have we", "haven't we", "did we", "are we", "Negative 'haven't' takes positive tag 'have we?'."),
    q("Kamal won't forget his admission card tomorrow, ___?", "will he", "won't he", "would he", "does he", "Negative 'won't' pairs with positive 'will he?'."),
    q("You can solve simultaneous equations easily, ___?", "can't you", "can you", "don't you", "couldn't you", "Positive modal 'can' takes negative tag 'can't you?'."),
    q("Let us plant shade trees around the playground, ___?", "shall we", "will we", "don't we", "aren't we", "Suggestions starting with 'Let's / Let us' always take 'shall we?'."),
    q("I am responsible for marking the attendance register, ___?", "aren't I", "amn't I", "isn't I", "don't I", "Affirmative 'I am' takes the irregular tag 'aren't I?'."),
    q("I am not late for the morning assembly, ___?", "am I", "aren't I", "is I", "do I", "Negative 'I am not' takes the straightforward tag 'am I?'."),
    q("Nobody answered that difficult riddle correctly, ___?", "did they", "didn't they", "did he", "wasn't it", "Negative subject 'Nobody' takes a positive tag with plural 'they'."),
    q("Everyone enjoyed the annual prize giving ceremony, ___?", "didn't they", "didn't he", "did they", "wasn't it", "'Everyone' takes the plural pronoun 'they' in question tags."),
    q("Someone left the science lab tap open, ___?", "didn't they", "did they", "wasn't it", "hasn't he", "Indefinite 'Someone' refers to 'they' in the question tag."),
    q("Nothing can stop a determined student from succeeding, ___?", "can it", "can't it", "can they", "does it", "'Nothing' is negative (takes positive tag) and refers to 'it'."),
    q("Everything is ready for the regional English day, ___?", "isn't it", "aren't they", "is it", "doesn't it", "'Everything' uses the singular neuter pronoun 'it' -> 'isn't it?'."),
    q("Close the classroom windows before leaving, ___?", "will you", "won't he", "shall I", "aren't you", "Imperative commands take 'will you?' (or 'won't you?')."),
    q("Don't spill ink on the new library books, ___?", "will you", "won't you", "do you", "didn't you", "Negative imperatives always take the positive tag 'will you?'."),
    q("Let the new student introduce himself first, ___?", "will you", "shall we", "aren't we", "don't you", "'Let + third person' is an imperative taking 'will you?', unlike 'Let's'."),
    q("Hardly anyone noticed the spelling error on the poster, ___?", "did they", "didn't they", "do they", "were they", "Semi-negative 'Hardly' requires a positive tag -> 'did they?'."),
    q("The express bus never arrives late on Mondays, ___?", "does it", "doesn't it", "is it", "did it", "'Never' makes the statement negative, so use positive 'does it?'."),
    q("She seldom watches television during exam month, ___?", "does she", "doesn't she", "is she", "did she", "Semi-negative 'seldom' pairs with positive tag 'does she?'."),
    q("There is very little ink left in this marker pen, ___?", "is there", "isn't there", "is it", "isn't it", "'Little' (without 'a') is negative; 'There is' takes 'is there?'."),
    q("There are a few mangoes on the lower branch, ___?", "aren't there", "are there", "aren't they", "isn't there", "'A few' is positive, and 'There are' forms 'aren't there?'."),
    q("Nimali used to live in Matara during childhood, ___?", "didn't she", "usedn't he", "doesn't she", "wasn't she", "'Used to' in the past takes 'didn't' in standard question tags."),
    q("We have to submit our essays before Friday, ___?", "don't we", "haven't we", "aren't we", "didn't we", "Main verb 'have to' uses auxiliary 'do' -> 'don't we?'."),
    q("Kamal has a brand-new bicycle, ___?", "doesn't he", "hasn't he", "isn't he", "didn't he", "Possessive main verb 'has' commonly uses 'doesn't he?'."),
    q("She has completed all six test papers already, ___?", "hasn't she", "doesn't she", "didn't she", "isn't she", "Auxiliary 'has' in Present Perfect repeats as 'hasn't she?'."),
    q("You had better consult the class teacher today, ___?", "hadn't you", "wouldn't you", "didn't you", "haven't you", "'Had better' takes 'hadn't you?' in the question tag."),
    q("They would rather travel by train than by bus, ___?", "wouldn't they", "hadn't they", "didn't they", "aren't they", "'Would rather' forms the tag with 'wouldn't'."),
    q("That ancient temple looks peaceful at dawn, ___?", "doesn't it", "isn't it", "didn't it", "hasn't it", "Simple Present 'looks' takes 'doesn't it?'."),
    q("These mangoes taste remarkably sweet and juicy, ___?", "don't they", "aren't they", "doesn't it", "didn't they", "Plural 'These mangoes' + Simple Present takes 'don't they?'."),
    q("It rained heavily throughout yesterday night, ___?", "didn't it", "wasn't it", "doesn't it", "hadn't it", "Simple Past 'rained' requires 'didn't it?'."),
    q("Your parents were thrilled with your term test report, ___?", "weren't they", "wasn't they", "didn't they", "aren't they", "Past verb 'were' repeats negatively as 'weren't they?'."),
    q("There won't be a rehearsal after school today, ___?", "will there", "won't there", "is there", "will it", "'There won't' reverses to 'will there?'."),
    q("Pass me that green highlighter on your desk, ___?", "will you", "shall we", "do you", "aren't you", "Polite request imperative uses 'will you?'."),
    q("You weren't listening when the bell rang, ___?", "were you", "weren't you", "did you", "are you", "Negative Past Continuous 'weren't' reverses to 'were you?'."),
    q("She could easily solve the puzzle on her own, ___?", "couldn't she", "can't she", "didn't she", "wouldn't she", "Modal 'could' becomes 'couldn't she?'."),
    q("We shouldn't waste clean drinking water, ___?", "should we", "shouldn't we", "do we", "must we", "Negative modal 'shouldn't' becomes 'should we?'."),
    q("He mustn't reveal the confidential password, ___?", "must he", "mustn't he", "does he", "should he", "'Mustn't' reverses to 'must he?'."),
    q("You will help your classmate revise for English, ___?", "won't you", "will you", "don't you", "aren't you", "Positive 'will' takes negative tag 'won't you?'."),
    q("Neither of the players was injured in the collision, ___?", "were they", "weren't they", "wasn't he", "did they", "'Neither' is negative, taking a positive tag with plural 'they'."),
    q("Each candidate has received an individual desk number, ___?", "haven't they", "hasn't it", "didn't he", "isn't it", "Singular 'Each candidate' commonly pairs with 'haven't they' (or 'hasn't he/she')."),
    q("This is the exact bus stop for Galle Road, ___?", "isn't it", "isn't this", "doesn't it", "wasn't it", "'This is' uses 'it' in the tag: 'isn't it?'."),
    q("Those aren't our science laboratory notebooks, ___?", "are they", "are those", "aren't they", "do they", "'Those aren't' uses 'they' in the tag: 'are they?'."),
    q("Reading newspapers regularly improves vocabulary, ___?", "doesn't it", "isn't it", "don't they", "hasn't it", "Gerund subject 'Reading...' takes pronoun 'it' -> 'doesn't it?'."),
    q("Learning a second language takes patience, ___?", "doesn't it", "isn't it", "didn't it", "hasn't it", "Gerund subject takes 'doesn't it?'."),
    q("She'd rather stay indoors than walk in the heat, ___?", "wouldn't she", "hadn't she", "didn't she", "isn't she", "'She'd rather' expands to 'She would rather' -> 'wouldn't she?'."),
    q("You'd better take your umbrella before leaving, ___?", "hadn't you", "wouldn't you", "didn't you", "won't you", "'You'd better' expands to 'You had better' -> 'hadn't you?'."),
    q("He's been working on the school mural all morning, ___?", "hasn't he", "isn't he", "wasn't he", "didn't he", "'He's been' expands to 'He has been' -> 'hasn't he?'."),
    q("She's going to participate in the essay contest, ___?", "isn't she", "hasn't she", "doesn't she", "wasn't she", "'She's going' expands to 'She is going' -> 'isn't she?'."),
    q("We ___ respect elderly passengers by offering our seats.", "ought to", "would rather", "needn't", "might not", "'Ought to' conveys social and moral duty."),
    q("___ you please lower your voice in the hospital corridor?", "Could", "Must", "Shall", "Need", "'Could you please...' is a polite request."),
    q("You ___ leave your bicycle unlocked outside the market.", "shouldn't", "needn't", "might", "could", "Warning advice against carelessness uses 'shouldn't'."),
    q("If we leave at dawn, we ___ reach Trincomalee by noon.", "should", "needn't", "mustn't", "used to", "'Should' expresses reasonable expectation of success."),
    q("Why ___ I clean the board? It's Ruwan's turn today!", "should", "mustn't", "ought", "had", "'Why should I...?' challenges an unfair expectation."),
    q("Even young children ___ learn simple polite greetings quickly.", "can", "mustn't", "needn't", "ought", "'Can' expresses general capability."),
    q("Wait here; the headmaster ___ see you in five minutes.", "will", "used to", "had to", "needn't", "Promised or scheduled immediate future action takes 'will'."),
    q("She ___ be very tired after organizing the whole concert.", "must", "can't", "needn't", "shall", "Logical conclusion from visible effort uses 'must be'."),
    q("They ___ have taken the wrong turn because they are still not here.", "must", "can't", "needn't", "shouldn't", "Strong past deduction uses 'must have + V3'."),
    q("He ___ have studied hard; his marks rose from 50 to 92.", "must", "can't", "needn't", "won't", "Strong deduction about past effort uses 'must have studied'."),
    q("She ___ have finished a 400-page novel in ten minutes!", "can't", "must", "should", "would", "Impossibility in the past is expressed with 'can't have + V3'."),
    q("We ___ conserve electricity by switching off unused classroom fans.", "must", "needn't", "can't", "wouldn't", "'Must' emphasizes civic/environmental responsibility."),
    q("You ___ touch live electric wires with wet hands.", "must never", "needn't", "don't have to", "might", "Critical safety prohibition uses 'must never'."),
    q("___ I open the classroom windows to let fresh air in?", "May", "Mustn't", "Ought", "Had", "Asking permission politely takes 'May I...'."),
    q("Nobody knows what really happened to the lost key, ___?", "do they", "don't they", "does he", "didn't they", "Negative 'Nobody' + Simple Present takes 'do they?'."),
    q("Very few students missed the morning bus today, ___?", "did they", "didn't they", "do they", "weren't they", "'Few' (without 'a') is negative -> positive tag 'did they?'."),
    q("A few students volunteered to decorate the stage, ___?", "didn't they", "did they", "weren't they", "don't they", "'A few' is positive -> negative tag 'didn't they?'."),
    q("Take a seat near the front row, ___?", "will you", "shall we", "aren't you", "don't I", "Invitation/polite imperative uses 'will you?' (or 'won't you?')."),
    q("Please do not forget to sign the attendance sheet, ___?", "will you", "won't you", "do you", "didn't you", "Negative imperative uses 'will you?'."),
    q("There used to be a large banyan tree near this junction, ___?", "didn't there", "usedn't it", "wasn't it", "hasn't there", "'There used to' takes 'didn't there?' in the question tag.")
  )
}
